import{_ as m,a0 as u,w as n,s as l,ao as p,I as a,x as e,a1 as i,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"如何轻松备份及恢复Firefox和Chromium的浏览器数据 | LCTT x X-CMD","titleTemplate":false,"description":"如何轻松备份及恢复Firefox和Chromium的浏览器数据 | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何轻松备份及恢复Firefox和Chromium的浏览器数据 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何轻松备份及恢复Firefox和Chromium的浏览器数据 | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/How to easily backup and reuse data of Firefox and Chromium","title":"如何轻松备份及恢复Firefox和Chromium的浏览器数据","tag":"201309","desc":""},"relativePath":"201309/How to easily backup and reuse data of Firefox and Chromium.md","filePath":"[post].md"}'),d={name:"201309/How to easily backup and reuse data of Firefox and Chromium.md"};function s(f,o,c,h,C,x){const t=u("Link");return n(),l("div",null,[o[11]||(o[11]=p('<h1 id="如何轻松备份及恢复firefox和chromium的浏览器数据" tabindex="-1">如何轻松备份及恢复Firefox和Chromium的浏览器数据 <a class="header-anchor" href="#如何轻松备份及恢复firefox和chromium的浏览器数据" aria-label="Permalink to “如何轻松备份及恢复Firefox和Chromium的浏览器数据”">​</a></h1><p>网络及网络中的网站、音乐、视频、图片、文件和书籍等内容在用户的IT生活中扮演着一个至关重要的角色。</p><p>在Ubuntu系统中，用户可以很轻松地安装开源的Chromium (apt://chromium-browser)浏览器，它与Ubuntu所带的默认浏览器Firefox一起，为用户提供了一种非常可靠的方式来访问网络上的内容。</p><p>然而很多情况下，用户会遇到不得不移动Firefox和Chromium产生的数据的情况，例如为了能在其它的Ubuntu设备或其它的电脑（放在其它地方而没有放在家里的电脑）上使用这些数据，或者为了在出现意外情况时（硬盘损坏、电脑丢失等）保护数据。</p><p>有几种基于远程同步的备份服务及工具，下面介绍一种方法，它可以提供快捷、可靠并且以随时可存取的方式来即时地（再）使用Firefox和Chromium的数据（这些数据包括网站历史记录、密码、下载历史、书签等基本上所有你使用Firefox和Chromium时产生的数据）。</p><p>这个方法是（在U盘里存储数据）：</p><ul><li><p>跳转到home文件夹下，然后按“Ctrl+H”键，显示出隐藏的文件夹。</p></li><li><p>将<code>.mozilla</code>文件夹复制到U盘中。</p></li></ul><p><img src="http://iloveubuntu.net/pictures_me/mozilla%20wed%20data%20backup.png" alt=""></p><ul><li>将<code>.config</code>文件夹中的<code>chromium</code>文件夹复制到U盘。</li></ul><p><img src="http://iloveubuntu.net/pictures_me/chromium%20web%20data%20backup.png" alt=""></p><p>现在你的U盘中就有<code>.mozilla</code>和<code>chromium</code>这两个文件夹了。</p><p>从U盘中将<code>.mozilla</code>和<code>chromium</code>这两个文件夹复制到新的（或旧的）Ubuntu设备中的相应位置（<code>.mozilla</code>在home目录下，<code>chromium</code> 在 <code>.config</code>目录下,——删除旧的将要被替换的<code>.mozilla</code> 和<code>chromium</code>文件夹——）打开Firefox和Chromium，用户就可以使用他们所有的网络数据了，至此，你就可以摆脱那些同步服务，高级复杂的方法和潜在的不可用性等问题了。</p><p>以防意外状况发生，你也可以用一个硬盘的分区来代替U盘备份。</p>',13)),a("p",null,[o[1]||(o[1]=e("via: ",-1)),i(t,{href:"http://iloveubuntu.net/how-easily-backup-and-reuse-data-firefox-and-chromium"},{default:r(()=>[...o[0]||(o[0]=[e("http://iloveubuntu.net/how-easily-backup-and-reuse-data-firefox-and-chromium",-1)])]),_:1})]),a("p",null,[o[4]||(o[4]=e("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[2]||(o[2]=[e("LCTT",-1)])]),_:1}),o[5]||(o[5]=e(" 原创翻译，",-1)),i(t,{href:"http://linux.cn/portal.php"},{default:r(()=>[...o[3]||(o[3]=[e("Linux中国",-1)])]),_:1}),o[6]||(o[6]=e(" 荣誉推出",-1))]),a("p",null,[o[8]||(o[8]=e("译者: [Linchenguang][] 校对：",-1)),i(t,{href:"http://linux.cn/space/14763"},{default:r(()=>[...o[7]||(o[7]=[e("Caroline",-1)])]),_:1})]),a("p",null,[o[10]||(o[10]=e("Linchenguang ",-1)),i(t,{href:"mailto:1215412538@qq.com"},{default:r(()=>[...o[9]||(o[9]=[e("1215412538@qq.com",-1)])]),_:1})])])}const g=m(d,[["render",s]]);export{_ as __pageData,g as default};
